use super::*;
fn decode<T:semio_framework_value::FromValue>(text:&str)->T{let mut receive=|_|true;let mut control=semio_framework_value::NativeDecodeControl::new(16*1024*1024,&mut receive);semio_framework_pack_json::from_json_str_controlled(text,semio_framework_pack_json::JsonMemberPolicy::Reject,&mut control).unwrap()}
fn observe<T>(work:impl FnOnce()->T)->(T,usize,usize){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(work);(value,heap.requested_bytes,heap.released_bytes)}
#[derive(semio_framework_value::RetireOwned)]
struct Sources{snapshot:FlowHostSnapshot,infos:HistoryFoldIndex<String,OperatorInfo>,result:Option<Tree>,expected:HistoryFoldIndex<String,Tree>}
#[test]
fn original_host_evaluation_source_preserves_duplicate_cycle_ports_and_nested_custody(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();for row in fixture["cases"].as_array().unwrap(){for copy in [1,3,64]{for cancel_at in [None,Some(0),Some(9),Some(37),Some(101)]{
  let text=serde_json::json!({"schema":"flow.host_snapshot","camera":{"x":0,"y":0,"zoom":1},"widgets":row["widgets"],"synapses":row["synapses"],"layout":{}}).to_string();let(mut sources,born,free)=observe(||Sources{snapshot:decode(&text),infos:row["kindInfos"].as_object().unwrap().iter().map(|(key,value)|(key.clone(),OperatorInfo{id:key.clone(),inputs:value["inputs"].as_array().unwrap().iter().map(|value|neural::ChannelSpec::requires(value.as_str().unwrap(),&[] as &[&str])).collect(),outputs:value["outputs"].as_array().unwrap().iter().map(|value|neural::ChannelSpec::provides(value.as_str().unwrap(),Vec::new())).collect(),..Default::default()})).collect(),result:None,expected:row["expectedClusters"].as_object().unwrap().iter().map(|(key,value)|(key.clone(),decode(&value.to_string()))).collect()});let original=born-free;let widgets=sources.snapshot.widgets.as_ptr();let synapses=sources.snapshot.synapses.as_ptr();let(mut cursor,born,free)=observe(FlowEvaluationSource::new);assert_eq!((born,free),(0,0));let mut births=0;let mut releases=0;let mut idle=0;let mut blocked=false;
  for turn in 0..1000000{if cancel_at==Some(turn){break}let demand=cursor.next_demands(&sources.snapshot,&sources.infos,copy).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};for _ in 0..2{let(result,born,free)=observe(||cursor.step(&sources.snapshot,&sources.infos,RetainedCloneGrant{maximum_items:0,..grant}).unwrap());assert!(result.is_none());assert_eq!(cursor.step_progress(),Default::default());assert_eq!((born,free),(0,0));}let(result,born,free)=observe(||cursor.step(&sources.snapshot,&sources.infos,grant).unwrap());let progress=cursor.step_progress();assert!(progress.fits(grant),"phase={} grant={grant:?} receipt={progress:?}",cursor.phase);assert_eq!((born,free),(progress.retained_capacity_bytes,progress.released_bytes),"phase={} turn={turn}",cursor.phase);births+=born;releases+=free;assert_eq!(sources.snapshot.widgets.as_ptr(),widgets);assert_eq!(sources.snapshot.synapses.as_ptr(),synapses);if demand.copy_bytes>copy{assert_eq!(demand.copy_bytes,row["minimumCopyBytes"].as_u64().unwrap() as usize);assert_eq!(progress,Default::default());assert_eq!((born,free),(0,0));blocked=true;break}if let Some(tree)=result{sources.result=Some(tree);break}if progress==RetainedCloneProgress::default(){idle+=1}else{idle=0}assert!(idle<64,"original Host source stalled phase={} demand={demand:?}",cursor.phase);}
  if cancel_at.is_none()&&copy<row["minimumCopyBytes"].as_u64().unwrap() as usize{assert!(blocked);assert!(sources.result.is_none());}if cancel_at.is_none()&&!blocked{let tree=sources.result.as_ref().unwrap();assert_eq!(tree.neurons.iter().map(|node|node.id.as_str()).collect::<Vec<_>>(),row["expectedIds"].as_array().unwrap().iter().map(|value|value.as_str().unwrap()).collect::<Vec<_>>());assert_eq!(tree.synapses.iter().map(|edge|vec![edge.from.as_str(),edge.from_port.as_str(),edge.to.as_str(),edge.to_port.as_str()]).collect::<Vec<_>>(),row["expectedPorts"].as_array().unwrap().iter().map(|value|value.as_array().unwrap().iter().map(|value|value.as_str().unwrap()).collect::<Vec<_>>()).collect::<Vec<_>>());for node in &tree.neurons{assert_eq!(serde_json::to_value(&node.params).unwrap(),row["expectedParams"][&node.id]);}for(key,_)in row["expectedClusters"].as_object().unwrap(){assert_eq!(tree.neurons.iter().find(|node|&node.id==key).unwrap().tree.as_deref().unwrap(),sources.expected.get(key).unwrap());}}
  cursor.begin_close();idle=0;for _ in 0..1000000{if cursor.terminal_is_empty(){break}let demand=cursor.next_close_demands(copy).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};let(step,born,free)=observe(||cursor.close_step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((born,free),(step.progress().retained_capacity_bytes,step.progress().released_bytes));births+=born;releases+=free;if step.progress()==RetainedCloneProgress::default(){idle+=1}else{idle=0}assert!(idle<64);}assert!(cursor.terminal_is_empty());let(_,born,free)=observe(||drop(cursor));assert_eq!((born,free),(0,0));
  let(mut owner,born,free)=observe(||ControlledRetirement::new(sources).unwrap_or_else(|_|unreachable!()));assert_eq!((born,free),(0,0));for _ in 0..1000000{if owner.terminal_is_empty(){break}let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:owner.next_capacity_byte_demand(copy).unwrap(),maximum_release_bytes:owner.next_release_byte_demand().unwrap(),maximum_depth:owner.next_depth_demand().unwrap()};let(step,born,free)=observe(||owner.step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((born,free),(step.progress().retained_capacity_bytes,step.progress().released_bytes));births+=born;releases+=free;}assert!(owner.terminal_is_empty());assert_eq!(original+births,releases);let(_,born,free)=observe(||drop(owner));assert_eq!((born,free),(0,0));eprintln!("[DEBUG] Original Host source id={} copy={copy} cancel={cancel_at:?} original={original} born={births} release={releases} terminalDrop=0",row["id"]);
 }}}
}
